using Microsoft.EntityFrameworkCore;
using PeopleHub.Infrastructure.Persistence;
using PeopleHub.Application.Services;
using PeopleHub.Domain.Entities;
namespace PeopleHub.Tests;
public class DepartmentApproverTests
{
 class User(int id=1,int emp=1,bool admin=true):ICurrentUser{public string Email=>$"department{id}@example.local";public int? EmployeeId=>emp;public int UserId=>id;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>admin;public bool Can(string p)=>admin;}
 static async Task<AppDbContext> Db(){var d=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();await d.Database.MigrateAsync();await SeedData.InitializeAsync(d,"Admin123!","Demo123!",new DateTime(2026,11,24));return d;}
 static WorkflowService W(AppDbContext d){var u=new User();return new(d,u,new(d,u,new(TimeProvider.System)));}
 static ApprovalService A(AppDbContext d,User u){var c=new AppClock(TimeProvider.System);var audit=new AuditService(d,u,c);return new(d,new(d,u),u,audit,new(d,u,c),c,W(d),new(d,u,audit,c));}
 [Fact]public void DepartmentManagerMustExistAndNotBeSubject(){var step=new WorkflowStep{Approver=ApproverType.DepartmentManager};var e=new Employee{Id=6,Department=new Department()};Assert.Throws<DomainException>(()=>RoutePlanner.Build([step],e,1));e.Department.ManagerId=6;Assert.Throws<DomainException>(()=>RoutePlanner.Build([step],e,1));e.Department.ManagerId=7;Assert.Equal("Employee#7",RoutePlanner.Build([step],e,1));Assert.Equal("HRManager",RoutePlanner.Build([new WorkflowStep{Approver=ApproverType.DepartmentManager,Threshold=2}],e,1));}
 [Fact]public async Task NewRouteCapturesDepartmentManagerWithoutChangingPendingRequests(){await using var d=await Db();var e=(await d.Set<Employee>().FindAsync(6))!;e.Department!.ManagerId=7;d.AddRange(new AppUser{Email="snap7@example.local",EmployeeId=7,RoleList=Roles.Employee,PasswordHash="unused",IsActive=true},new AppUser{Email="snap8@example.local",EmployeeId=8,RoleList=Roles.Employee,PasswordHash="unused",IsActive=true});await d.SaveAsync();await W(d).AddStepAsync("Overtime",ApproverType.DepartmentManager,null,null);var first=new OvertimeRequest{EmployeeId=6};await W(d).RouteRequestAsync("Overtime",first,e,1);Assert.EndsWith("Employee#7",first.Route);var route=first.Route;e.Department.ManagerId=8;await d.SaveAsync();var second=new OvertimeRequest{EmployeeId=6};await W(d).RouteRequestAsync("Overtime",second,e,1);Assert.EndsWith("Employee#8",second.Route);Assert.Equal(route,first.Route);Assert.Equal(first.WorkflowRevisionHash,second.WorkflowRevisionHash);}
 [Fact]public async Task CapturedApproverAndDelegateActButReplacementManagerCannot(){await using var d=await Db();var target=new AppUser{Email="department7@example.local",EmployeeId=7,RoleList=Roles.Employee,PasswordHash="unused",IsActive=true};var replacement=new AppUser{Email="department8@example.local",EmployeeId=8,RoleList=Roles.Employee,PasswordHash="unused",IsActive=true};d.AddRange(target,replacement);var r=new OvertimeRequest{EmployeeId=6,Route="Employee#7,HRManager",Hours=1,Date=new(2026,11,24)};d.Add(r);await d.SaveAsync();await Assert.ThrowsAsync<DomainException>(()=>A(d,new(replacement.Id,8,false)).ApproveAsync("Overtime",r.Id,"Wrong manager"));Assert.Contains(await A(d,new(target.Id,7,false)).ListAsync("Overtime",null,true),x=>x.Id==r.Id);d.Add(new Delegation{FromEmployeeId=7,ToEmployeeId=8,StartDate=DateTime.Today.AddDays(-1),EndDate=DateTime.Today.AddDays(1)});await d.SaveAsync();await A(d,new(replacement.Id,8,false)).ApproveAsync("Overtime",r.Id,"Delegated department review");r=(await d.Set<OvertimeRequest>().FindAsync(r.Id))!;Assert.Equal(1,r.StageIndex);Assert.Equal(RequestStatus.Pending,r.Status);}
 [Fact]public async Task AdminCannotConfigureUnknownRoleOrInvalidApproverType(){await using var d=await Db();await Assert.ThrowsAsync<DomainException>(()=>W(d).AddStepAsync("Leave",(ApproverType)99,null,null));await Assert.ThrowsAsync<DomainException>(()=>W(d).AddStepAsync("Leave",ApproverType.Role,["Employee#7"],null));}
 [Fact]public async Task MissingActiveDepartmentApproverAccountBlocksRequestAndNoRevisionIsStaged(){await using var d=await Db();var e=(await d.Set<Employee>().FindAsync(6))!;e.Department!.ManagerId=9;foreach(var u in await d.Set<AppUser>().Where(x=>x.EmployeeId==9).ToListAsync())u.IsActive=false;await d.SaveAsync();await W(d).AddStepAsync("Overtime",ApproverType.DepartmentManager,null,null);await Assert.ThrowsAsync<DomainException>(()=>W(d).RouteRequestAsync("Overtime",new OvertimeRequest(),e,1));Assert.DoesNotContain(d.ChangeTracker.Entries<WorkflowRevision>(),x=>x.State==EntityState.Added);}
 [Fact]public async Task DepartmentReminderTargetsRecordedEmployeeNotNewManager(){await using var d=await Db();var c=new AppClock(TimeProvider.System);var target=new AppUser{Email="reminder-dept7@example.local",EmployeeId=7,RoleList=Roles.Employee,PasswordHash="unused",IsActive=true};d.Add(target);var r=new OvertimeRequest{EmployeeId=6,Route="Employee#7",Hours=1,Date=c.Today,CreatedAt=c.UtcNow.AddHours(-3)};d.Add(r);d.Add(new AppSetting{Key="Workflow.ReminderHours.Overtime",Value="1"});await d.SaveAsync();await new ApprovalReminders(d,c).RunAsync();Assert.Contains(await d.Set<ApprovalReminder>().Where(x=>x.RequestId==r.Id&&x.Kind=="Overtime").ToListAsync(),x=>x.UserId==target.Id);}
 [Fact]public async Task NotificationResolvesCapturedDepartmentEmployee(){await using var d=await Db();var target=new AppUser{Email="notify-dept7@example.local",EmployeeId=7,RoleList=Roles.Employee,PasswordHash="unused",IsActive=true};d.Add(target);await d.SaveAsync();var clock=new AppClock(TimeProvider.System);await new NotificationService(d,new User(),clock).NotifyStageAsync(new OvertimeRequest{EmployeeId=6,Route="Employee#7"},"Fictional department approval");await d.SaveAsync();Assert.Contains(await d.Set<Notification>().ToListAsync(),x=>x.UserId==target.Id&&x.Details=="Fictional department approval");}
}
public class SkipLevelApproverTests
{
 static readonly WorkflowStep Step=new(){Approver=ApproverType.SkipLevelManager};
 static Dictionary<int,int?> Chain(int? m6,int? m7)=>new(){[6]=m6,[7]=m7,[8]=null};
 [Fact]public void CapturesManagersManager(){var e=new Employee{Id=5,ManagerId=7};Assert.Equal("Employee#8",RoutePlanner.Build([Step],e,1,false,Chain(7,8)));}
 [Fact]public void MissingSelfOrLoopingChainBlocks()
 {
  Assert.Throws<DomainException>(()=>RoutePlanner.Build([Step],new Employee{Id=5},1,false,Chain(null,8)));
  Assert.Throws<DomainException>(()=>RoutePlanner.Build([Step],new Employee{Id=5,ManagerId=7},1,false,Chain(7,null)));
  Assert.Throws<DomainException>(()=>RoutePlanner.Build([Step],new Employee{Id=5,ManagerId=7},1,false,null));
  Assert.Throws<DomainException>(()=>RoutePlanner.Build([Step],new Employee{Id=5,ManagerId=7},1,false,new Dictionary<int,int?>{[7]=5}));
  Assert.Throws<DomainException>(()=>RoutePlanner.Build([Step],new Employee{Id=5,ManagerId=7},1,false,new Dictionary<int,int?>{[7]=7}));
 }
 [Fact]public void ThresholdStillSkipsStepWithoutBlocking(){var e=new Employee{Id=5};Assert.Equal("HRManager",RoutePlanner.Build([new WorkflowStep{Approver=ApproverType.SkipLevelManager,Threshold=5}],e,1,false,null));}
 [Fact]public void TokenAndDuplicateGuard(){Assert.Equal("SkipLevelManager",Step.Token);}
}
